import re

from django.db import migrations, models


def categorize_groups(apps, schema_editor):
    """把历史 MIDDLE 中明确的高中组迁到 HIGH，其余保持原值。

    旧口径只有 PRIMARY/MIDDLE，高中被并进 MIDDLE；这里只处理名称/年龄
    能明确判断为高中的组，避免把含义不明的测试数据误改。
    """
    EventGroup = apps.get_model("events", "EventGroup")
    for group in EventGroup.objects.all().only("pk", "name", "category"):
        name = (group.name or "").upper()
        target = None
        if "高中" in name or re.search(r"U(18|19|20)", name):
            target = "HIGH"
        elif "小学" in name or "U12" in name:
            target = "PRIMARY"
        elif "初中" in name or re.search(r"U(13|14|15)", name):
            target = "MIDDLE"
        if target and group.category != target:
            group.category = target
            group.save(update_fields=["category"])


